package dev.henrique.inventory; import dev.henrique.inventory.domain.*; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class DomainUnitTest { @Test void inventoryNeverGoesNegative(){Product p=new Product("A","A");Inventory i=new Inventory(p,2);assertThatThrownBy(()->i.reserve(3)).isInstanceOf(InsufficientInventoryException.class);assertThat(i.getAvailableQuantity()).isEqualTo(2);}@Test void pendingMayConfirmButConfirmedCannotCancel(){Reservation r=new Reservation();r.transitionTo(ReservationStatus.CONFIRMED);assertThatThrownBy(()->r.transitionTo(ReservationStatus.CANCELLED)).isInstanceOf(InvalidTransitionException.class);}}
